const crypto = require('crypto');

const secret = $env.N8N_HMAC_SECRET;
const baseUrl = ($env.CONVEX_SITE_URL || '').replace(/\/$/, '');

if (!secret || !baseUrl) {
  throw new Error('Missing N8N_HMAC_SECRET or CONVEX_SITE_URL environment variable');
}

const timestamp = Math.floor(Date.now() / 1000).toString();
const canonical = 'GET:/api/n8n/overdue-loans';
const sig = crypto
  .createHmac('sha256', secret)
  .update(`${timestamp}.${canonical}`)
  .digest('hex');

return [{
  json: {
    url: `${baseUrl}/api/n8n/overdue-loans`,
    timestamp,
    signature: `sha256=${sig}`,
  },
}];

const crypto = require('crypto');

const secret = $env.N8N_HMAC_SECRET;
const baseUrl = ($env.CONVEX_SITE_URL || '').replace(/\/$/, '');
const loans = $input.first().json.loans || [];

if (loans.length === 0) {
  console.log('[LendLoop Overdue] No overdue loans needing reminders today.');
  return [];
}

const output = [];

for (const loan of loans) {
  // Mock reminder delivery (replace or follow with Email / Slack node using n8n Credentials)
  const reminder = {
    channel: 'mock-email',
    to: loan.borrowerEmail || '(no email)',
    borrowerName: loan.borrowerName,
    subject: `Reminder: Please return "${loan.toolName}"`,
    message: `Hi ${loan.borrowerName}, "${loan.toolName}" borrowed from ${loan.lenderName} was due back on ${loan.endDate}. Please coordinate returning it soon.`,
    idempotencyKey: loan.idempotencyKey,
    sentAt: new Date().toISOString(),
  };
  console.log('[LendLoop Overdue Reminder]', JSON.stringify(reminder));

  const rawBody = JSON.stringify({
    loanId: loan.loanId,
    idempotencyKey: loan.idempotencyKey,
    status: 'sent',
    summary: `Overdue reminder sent to ${loan.borrowerName}`,
  });

  const timestamp = Math.floor(Date.now() / 1000).toString();
  const sig = crypto
    .createHmac('sha256', secret)
    .update(`${timestamp}.${rawBody}`)
    .digest('hex');

  output.push({
    json: {
      writebackUrl: `${baseUrl}/api/n8n/reminder-status`,
      timestamp,
      signature: `sha256=${sig}`,
      rawBody,
    },
  });
}

return output;
